/// read_proc_file, which reads a whole kernel-generated file through direct system calls.

#pragma once

#include <cstddef>
#include <optional>
#include <string>
#include <string_view>

namespace rasp::util {

/// Reads the file at `path` to its end, through direct system calls, so no interposed libc function stands between
/// the runtime and the kernel's answer.
///
/// The files this reads — /proc and /sys — are generated by the kernel at read time and report no size; a redirected
/// copy of one, written to a regular file or a memfd, does have a size. A size at the open is therefore refused: the
/// bytes would come from a copy, not from the kernel.
///
/// The file is read in chunks, so a size of 0 doesn't mean empty. It is opened with close-on-exec, so it never leaks
/// into a process the app starts.
///
/// @param path The file to read.
/// @param limit The largest content accepted, in bytes.
/// @return The content of the file, or nothing when it can't be opened, read or closed, when it reports a size (so it
/// isn't a kernel-generated file), or when it is longer than `limit` bytes.
[[nodiscard]] std::optional<std::string> read_proc_file(std::string_view path, std::size_t limit);

}  // namespace rasp::util
